//! C ABI types and constants for Turbo.
//!
//! This crate is the single source of the public C header
//! (`include/turbo/turbo.h`, generated by cbindgen from `turbo-capi`, which
//! re-exports everything here). Every type is `#[repr(C)]`, every enumeration
//! in ABI position is a `u32` with named constants, every public struct starts
//! with `struct_size`, and every length is fixed-width.
//!
//! Rules (see PLAN.md section 4.3):
//! - A caller sets `struct_size = sizeof(struct)` for the version it compiled
//!   against. The library reads only fields below that size. Appended fields
//!   must have a zero value meaning "old behavior".
//! - Strings are UTF-8 pointer+length views ([`turbo_text`]). Fixed `char`
//!   arrays in output structs are NUL-terminated UTF-8.
//! - Handles are opaque and reference counted inside the library. Child
//!   handles retain their parents.
//! - Errors are caller-owned ([`turbo_error`]); no thread-local or shared
//!   error state exists.

#![no_std]
#![allow(non_camel_case_types)]
#![deny(missing_docs)]

use core::ffi::c_char;
use core::ffi::c_void;

pub mod provider;
pub mod versioned;
pub use provider::*;
pub use versioned::Versioned;

/// ABI version. Bumped only for a breaking layout or semantic change.
pub const TURBO_ABI_VERSION: u32 = 2;

// ---------------------------------------------------------------------------
// Status codes
// ---------------------------------------------------------------------------
//
// Graded so callers can branch on the hundreds digit:
//   0x000 ok
//   0x1xx argument / contract violation by the caller
//   0x2xx unsupported on this device, model, or option (capability)
//   0x3xx resource (memory, busy, capacity)
//   0x4xx device / runtime / provider failure
//   0x5xx bundle integrity
//   0x6xx internal

/// Success.
pub const TURBO_OK: i32 = 0;
/// A caller argument is invalid; `turbo_error.field` may name it.
pub const TURBO_E_INVALID_ARGUMENT: i32 = 0x100;
/// A descriptor's `struct_size` is not one this library understands.
pub const TURBO_E_INVALID_STRUCT_SIZE: i32 = 0x101;
/// A text view is not valid UTF-8.
pub const TURBO_E_INVALID_UTF8: i32 = 0x102;
/// A handle is null or of the wrong kind.
pub const TURBO_E_INVALID_HANDLE: i32 = 0x103;
/// A shape, stride, or byte count is inconsistent or overflows.
pub const TURBO_E_INVALID_SHAPE: i32 = 0x104;
/// The operation is not valid in the handle's current state (for example
/// `run` before any input was written, or use after cancel).
pub const TURBO_E_INVALID_STATE: i32 = 0x105;
/// A constant (dtype, task, option value) is outside the known set.
pub const TURBO_E_INVALID_ENUM: i32 = 0x106;
/// The requested combination is unsupported here; see `message`.
pub const TURBO_E_UNSUPPORTED: i32 = 0x200;
/// An option field is not honored by this provider for this model;
/// `turbo_error.field` is the 1-based field index in the options struct.
pub const TURBO_E_UNSUPPORTED_OPTION: i32 = 0x201;
/// The task is not offered on this device for this model.
pub const TURBO_E_UNSUPPORTED_TASK: i32 = 0x202;
/// The dtype is not supported in the requested placement.
pub const TURBO_E_UNSUPPORTED_DTYPE: i32 = 0x203;
/// The placement is not supported by this device.
pub const TURBO_E_UNSUPPORTED_PLACEMENT: i32 = 0x204;
/// Declared in the header but not implemented in this build. Never a silent fallback.
pub const TURBO_E_NOT_IMPLEMENTED: i32 = 0x205;
/// The modality is not offered on this device for this model.
pub const TURBO_E_UNSUPPORTED_MODALITY: i32 = 0x206;
/// Allocation failed.
pub const TURBO_E_OUT_OF_MEMORY: i32 = 0x300;
/// The session or generation has an operation or result lease in flight.
pub const TURBO_E_BUSY: i32 = 0x301;
/// The provider is refusing new work; retry later.
pub const TURBO_E_OVERLOADED: i32 = 0x302;
/// The request exceeds a declared capacity (batch, sequence, output size).
pub const TURBO_E_CAPACITY: i32 = 0x303;
/// No device matches the selector.
pub const TURBO_E_DEVICE_NOT_FOUND: i32 = 0x400;
/// The device exists but cannot be used (driver missing, busy, failed probe).
pub const TURBO_E_DEVICE_UNAVAILABLE: i32 = 0x401;
/// The vendor runtime reported an error; `message` carries its text.
pub const TURBO_E_RUNTIME: i32 = 0x402;
/// A provider library could not be loaded or did not export the entry point.
pub const TURBO_E_PROVIDER_LOAD: i32 = 0x403;
/// A provider library targets a different ABI version.
pub const TURBO_E_ABI_MISMATCH: i32 = 0x404;
/// The operation was cancelled by the caller.
pub const TURBO_E_CANCELLED: i32 = 0x405;
/// The bundle directory or a required file is missing.
pub const TURBO_E_BUNDLE_NOT_FOUND: i32 = 0x500;
/// The bundle manifest is malformed or declares an unknown version.
pub const TURBO_E_BUNDLE_INVALID: i32 = 0x501;
/// A bundle file does not match its recorded hash.
pub const TURBO_E_BUNDLE_INTEGRITY: i32 = 0x502;
/// The bundle is valid but no artifact in it is loadable by this provider.
pub const TURBO_E_BUNDLE_NO_ARTIFACT: i32 = 0x503;
/// A bug in the library or provider.
pub const TURBO_E_INTERNAL: i32 = 0x600;
/// A panic or exception was caught at the language boundary.
pub const TURBO_E_PANIC: i32 = 0x601;

