// ---------------------------------------------------------------------------
// Capability bits (u64)
// ---------------------------------------------------------------------------

/// The device can execute asynchronously (`turbo_session_submit` + fences).
pub const TURBO_CAP_ASYNC: u64 = 0x1;
/// Caller host memory can be imported without a copy.
pub const TURBO_CAP_HOST_PTR_IMPORT: u64 = 0x2;
/// Results can stay resident on the device and be exported.
pub const TURBO_CAP_DEVICE_RESULT: u64 = 0x4;
/// A caller-owned queue/stream can be imported.
pub const TURBO_CAP_EXTERNAL_QUEUE: u64 = 0x8;
/// DMA-BUF import.
pub const TURBO_CAP_DMABUF: u64 = 0x10;
/// Host and device share one address space (unified / USM shared).
pub const TURBO_CAP_UNIFIED_MEMORY: u64 = 0x20;
/// Sessions may run any shape up to their maximum without recompiling.
pub const TURBO_CAP_DYNAMIC_SHAPE: u64 = 0x40;
/// Sessions on one model share weights.
pub const TURBO_CAP_WEIGHT_SHARING: u64 = 0x80;
/// Tokenization runs on the device from raw UTF-8.
pub const TURBO_CAP_DEVICE_TOKENIZE: u64 = 0x100;
/// Post-processing (softmax, aggregation) runs on the device.
pub const TURBO_CAP_DEVICE_POSTPROCESS: u64 = 0x200;
/// Deterministic results across runs for the same inputs and seed.
pub const TURBO_CAP_DETERMINISTIC: u64 = 0x400;

/// Option `truncate` is honored.
pub const TURBO_CAP_OPT_TRUNCATE: u64 = 0x10000;
/// Option `max_tokens` is honored.
pub const TURBO_CAP_OPT_MAX_TOKENS: u64 = 0x20000;
/// Option `prompt_role` is honored.
pub const TURBO_CAP_OPT_PROMPT_ROLE: u64 = 0x40000;
/// Option `normalize` may differ from the model contract.
pub const TURBO_CAP_OPT_NORMALIZE: u64 = 0x80000;
/// Option `pooling` may differ from the model contract.
pub const TURBO_CAP_OPT_POOLING_OVERRIDE: u64 = 0x100000;
/// Option `output_dim` (Matryoshka truncation) is honored.
pub const TURBO_CAP_OPT_OUTPUT_DIM: u64 = 0x200000;
/// Option `output_dtype` is honored.
pub const TURBO_CAP_OPT_OUTPUT_DTYPE: u64 = 0x400000;
/// Rerank `top_n` and sorted output are computed by the provider.
pub const TURBO_CAP_OPT_TOP_N: u64 = 0x800000;
/// Token-classification `aggregation` may differ from the model contract.
pub const TURBO_CAP_OPT_AGGREGATION: u64 = 0x1000000;
/// Rerank and classify `raw_scores` (logits instead of activated scores) is honored.
pub const TURBO_CAP_OPT_RAW_SCORES: u64 = 0x2000000;

/// Generation: structured output as a GBNF grammar (`structured_kind =
/// TURBO_STRUCTURED_GRAMMAR`); a JSON schema needs `TURBO_CAP_OPT_GEN_JSON_SCHEMA` too.
pub const TURBO_CAP_OPT_GEN_STRUCTURED: u64 = 0x100000000;
/// Generation: tool definitions in the prompt template.
pub const TURBO_CAP_OPT_GEN_TOOLS: u64 = 0x200000000;
/// Generation: `n_sequences > 1`.
pub const TURBO_CAP_OPT_GEN_N: u64 = 0x400000000;
/// Generation: `logit_bias`.
pub const TURBO_CAP_OPT_GEN_LOGIT_BIAS: u64 = 0x800000000;
/// Generation: presence / frequency / repeat penalties.
pub const TURBO_CAP_OPT_GEN_PENALTIES: u64 = 0x1000000000;
/// Generation: per-token logprobs.
pub const TURBO_CAP_OPT_GEN_LOGPROBS: u64 = 0x2000000000;
/// Generation: stop strings (as opposed to stop token ids only).
pub const TURBO_CAP_OPT_GEN_STOP_STRINGS: u64 = 0x4000000000;
/// Generation: `seed` is honored (implies reproducible sampling).
pub const TURBO_CAP_OPT_GEN_SEED: u64 = 0x8000000000;
/// Generation: sampling controls `temperature`, `top_k`, `top_p`, `min_p`.
pub const TURBO_CAP_OPT_GEN_SAMPLING: u64 = 0x10000000000;
/// Generation: `min_new_tokens`.
pub const TURBO_CAP_OPT_GEN_MIN_TOKENS: u64 = 0x20000000000;
/// Generation: `echo` (the prompt is included in the output text).
pub const TURBO_CAP_OPT_GEN_ECHO: u64 = 0x40000000000;
/// Generation: stop token ids.
pub const TURBO_CAP_OPT_GEN_STOP_TOKENS: u64 = 0x80000000000;
/// Generation: `structured_kind = TURBO_STRUCTURED_JSON_SCHEMA` (the
/// provider turns a JSON schema into a constraint itself). Needs
/// `TURBO_CAP_OPT_GEN_STRUCTURED` as well; that bit alone covers GBNF.
pub const TURBO_CAP_OPT_GEN_JSON_SCHEMA: u64 = 0x100000000000;

// ---------------------------------------------------------------------------
// Views and errors
// ---------------------------------------------------------------------------

/// UTF-8 view. `ptr` may be NULL only when `len == 0`. Not NUL-terminated.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_text {
    /// Start of the bytes.
    pub ptr: *const c_char,
    /// Byte length.
    pub len: u64,
}

/// Key / value pair of UTF-8 views, used for provider options and request parameters.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_kv {
    /// Option name.
    pub key: turbo_text,
    /// Option value.
    pub value: turbo_text,
}

/// Length of `turbo_error.message` including the terminating NUL.
pub const TURBO_ERROR_MESSAGE_LEN: usize = 496;

/// Caller-owned error record. On success `code == 0` and `message[0] == 0`.
/// The message is always NUL-terminated UTF-8. `field` is the 1-based index
/// of the offending field in the descriptor for `TURBO_E_UNSUPPORTED_OPTION`
/// and `TURBO_E_INVALID_ARGUMENT`, otherwise 0. May be NULL in any call, in
/// which case only the status code is returned.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct turbo_error {
    /// `sizeof(turbo_error)`.
    pub struct_size: u32,
    /// Status code.
    pub code: i32,
    /// Offending field index, or 0.
    pub field: u32,
    /// NUL-terminated message.
    pub message: [c_char; TURBO_ERROR_MESSAGE_LEN],
}

// ---------------------------------------------------------------------------
// Opaque handles
// ---------------------------------------------------------------------------

/// Library instance owning the provider registry. Thread-safe.
pub struct turbo_runtime {
    _private: [u8; 0],
}
/// Device plus memory domain. Thread-safe.
pub struct turbo_context {
    _private: [u8; 0],
}
/// Typed memory in a placement. Retains its context.
pub struct turbo_buffer {
    _private: [u8; 0],
}
/// Loaded model. Immutable. Retains its context.
pub struct turbo_model {
    _private: [u8; 0],
}
/// Execution workspace with a fixed maximum shape. Single owner. Retains its model.
pub struct turbo_session {
    _private: [u8; 0],
}
/// Leased output of the last operation on a session. Retains its session.
pub struct turbo_result {
    _private: [u8; 0],
}
/// Streaming generation state. Single owner. Retains its model.
pub struct turbo_generation {
    _private: [u8; 0],
}
/// Tokenizer loaded from a bundle. Thread-safe.
pub struct turbo_tokenizer {
    _private: [u8; 0],
}
/// Chunk plan over caller-owned text.
pub struct turbo_chunk_plan {
    _private: [u8; 0],
}

// ---------------------------------------------------------------------------
// Runtime and devices
// ---------------------------------------------------------------------------

/// Log callback: `level` 0 error, 1 warn, 2 info, 3 debug; `message` is a UTF-8 view valid for the call.
pub type turbo_log_fn = Option<unsafe extern "C" fn(user_data: *mut c_void, level: u32, message: turbo_text)>;

/// Runtime creation descriptor.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_runtime_desc {
    /// `sizeof(turbo_runtime_desc)`.
    pub struct_size: u32,
    /// `TURBO_RUNTIME_*` flags.
    pub flags: u32,
    /// Number of explicit provider library paths.
    pub n_provider_paths: u32,
    /// Reserved; must be 0.
    pub reserved: u32,
    /// Explicit provider library paths (loaded in order, errors reported).
    pub provider_paths: *const turbo_text,
    /// Optional log sink.
    pub log: turbo_log_fn,
    /// Passed to `log`.
    pub log_user_data: *mut c_void,
}

/// Device selector for `turbo_runtime_select_device`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_device_selector {
    /// `sizeof(turbo_device_selector)`.
    pub struct_size: u32,
    /// `TURBO_SELECT_AUTO` or `TURBO_SELECT_EXPLICIT`.
    pub policy: u32,
    /// Bitmask of accepted `TURBO_DEVICE_*` kinds shifted (`1 << kind`); 0 = any non-CPU for AUTO.
    pub kind_mask: u32,
    /// Ordinal within the provider (EXPLICIT only).
    pub ordinal: u32,
    /// Provider id, empty = any.
    pub provider_id: turbo_text,
    /// Vendor substring, empty = any.
    pub vendor: turbo_text,
}

/// Static device description.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct turbo_device_info {
    /// `sizeof(turbo_device_info)`.
    pub struct_size: u32,
    /// `TURBO_DEVICE_*`.
    pub kind: u32,
    /// Ordinal within the provider.
    pub ordinal: u32,
    /// PCI vendor id where known, else 0.
    pub vendor_id: u32,
    /// `TURBO_CAP_*` bits.
    pub caps: u64,
    /// Total device memory in bytes, 0 if unknown.
    pub memory_total: u64,
    /// Free device memory in bytes at query time, 0 if unknown.
    pub memory_free: u64,
    /// Human-readable device name.
    pub name: [c_char; 128],
    /// Vendor name.
    pub vendor: [c_char; 64],
    /// Provider id (for example `cuda`, `openvino`, `mock`).
    pub provider_id: [c_char; 32],
    /// Provider library version.
    pub provider_version: [c_char; 32],
    /// Vendor runtime version.
    pub runtime_version: [c_char; 64],
    /// Driver version, empty if not applicable.
    pub driver_version: [c_char; 64],
}

/// One cell of the capability matrix for (device, task, modality).
#[repr(C)]
#[derive(Clone, Copy)]
pub struct turbo_capability {
    /// `sizeof(turbo_capability)`.
    pub struct_size: u32,
    /// `TURBO_CAP_UNSUPPORTED` .. `TURBO_CAP_SUPPORTED`.
    pub status: u32,
    /// Compute dtype used (`TURBO_DTYPE_*`), 0 if not applicable.
    pub dtype: u32,
    /// Reference dtype the precision figures are measured against, 0 if none.
    pub reference_dtype: u32,
    /// Measured cosine-similarity floor against the reference; 0 if unmeasured.
    pub cosine_floor: f32,
    /// Measured maximum absolute error against the reference; 0 if unmeasured.
    pub max_abs_error: f32,
    /// 1 if results are bit-reproducible across runs.
    pub deterministic: u32,
    /// Reserved; 0.
    pub reserved: u32,
    /// Free-text qualification note (receipt id, limits).
    pub notes: [c_char; 128],
}

