/// One chat message for template application.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_message {
    /// Role (`system`, `user`, `assistant`, `tool`).
    pub role: turbo_text,
    /// Content.
    pub content: turbo_text,
}

/// Logit bias entry.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default)]
pub struct turbo_logit_bias {
    /// Token id.
    pub token: i32,
    /// Additive bias.
    pub bias: f32,
}

/// Generation descriptor. Capability-gated fields are marked; an unsupported
/// non-zero field fails with `TURBO_E_UNSUPPORTED_OPTION` naming it.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_generate_desc {
    /// `sizeof(turbo_generate_desc)`.
    pub struct_size: u32,
    /// Maximum new tokens; 0 = model default.
    pub max_new_tokens: u32,
    /// Minimum new tokens before EOS is allowed. Gated by `TURBO_CAP_OPT_GEN_MIN_TOKENS`.
    pub min_new_tokens: u32,
    /// Sequences to generate; 0 or 1 = one. Gated by `TURBO_CAP_OPT_GEN_N`.
    pub n_sequences: u32,
    /// Sampling temperature; 0 = greedy. Gated by `TURBO_CAP_OPT_GEN_SAMPLING`.
    pub temperature: f32,
    /// Top-k; 0 = off. Gated by `TURBO_CAP_OPT_GEN_SAMPLING`.
    pub top_k: u32,
    /// Top-p; 0 or 1 = off. Gated by `TURBO_CAP_OPT_GEN_SAMPLING`.
    pub top_p: f32,
    /// Min-p; 0 = off. Gated by `TURBO_CAP_OPT_GEN_SAMPLING`.
    pub min_p: f32,
    /// Repeat penalty; 0 or 1 = off. Gated by `TURBO_CAP_OPT_GEN_PENALTIES`.
    pub repeat_penalty: f32,
    /// Presence penalty; 0 = off. Gated.
    pub presence_penalty: f32,
    /// Frequency penalty; 0 = off. Gated.
    pub frequency_penalty: f32,
    /// 1 = use `seed`. Gated by `TURBO_CAP_OPT_GEN_SEED`.
    pub has_seed: u32,
    /// Random seed.
    pub seed: u64,
    /// Number of stop strings. Gated by `TURBO_CAP_OPT_GEN_STOP_STRINGS`.
    /// The stream ends with `TURBO_FINISH_STOP` when the generated text
    /// would contain one; the text delivered ends before the match, and the
    /// matched string and whatever followed it in the same piece are never
    /// delivered. Text that could still complete a stop string is held back
    /// until it cannot, so a match spanning pieces is caught too.
    pub n_stop: u32,
    /// Number of stop token ids. Gated by `TURBO_CAP_OPT_GEN_STOP_TOKENS`.
    pub n_stop_tokens: u32,
    /// Stop strings.
    pub stop: *const turbo_text,
    /// Stop token ids.
    pub stop_tokens: *const i32,
    /// Number of logit bias entries. Gated by `TURBO_CAP_OPT_GEN_LOGIT_BIAS`.
    pub n_logit_bias: u32,
    /// Top logprobs per token to return; 0 = none. Gated by `TURBO_CAP_OPT_GEN_LOGPROBS`.
    pub logprobs: u32,
    /// Logit bias entries.
    pub logit_bias: *const turbo_logit_bias,
    /// `TURBO_STRUCTURED_*`. Gated by `TURBO_CAP_OPT_GEN_STRUCTURED`.
    pub structured_kind: u32,
    /// 1 = include the prompt in the output text. Gated by `TURBO_CAP_OPT_GEN_ECHO`.
    pub echo: u32,
    /// Schema or grammar text.
    pub structured: turbo_text,
    /// Number of tool definitions (JSON). Gated by `TURBO_CAP_OPT_GEN_TOOLS`.
    pub n_tools: u32,
    /// Number of provider options.
    pub n_options: u32,
    /// Tool definitions.
    pub tools: *const turbo_text,
    /// Provider options (unknown keys are rejected).
    pub options: *const turbo_kv,
}

/// One step of generation. Pointers are valid until the next `step`, `cancel`, or `release`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct turbo_generation_chunk {
    /// `sizeof(turbo_generation_chunk)`.
    pub struct_size: u32,
    /// Sequence index (0 unless `n_sequences > 1`).
    pub sequence: u32,
    /// Number of new token ids in this chunk.
    pub n_tokens: u32,
    /// Number of logprob entries (`n_tokens * logprobs`).
    pub n_logprobs: u32,
    /// New token ids.
    pub tokens: *const i32,
    /// Decoded text for the new tokens (may be empty mid-codepoint).
    pub text: turbo_text,
    /// Logprobs, or NULL.
    pub logprobs: *const f32,
    /// 1 when this sequence is finished.
    pub done: u32,
    /// `TURBO_FINISH_*` when `done`.
    pub finish_reason: u32,
    /// Prompt tokens consumed (reported on the first chunk).
    pub prompt_tokens: u32,
    /// Total generated tokens so far in this sequence.
    pub generated_tokens: u32,
}

/// Push-generation callback. Return `TURBO_STREAM_CONTINUE` or `TURBO_STREAM_STOP`.
pub type turbo_stream_fn =
    Option<unsafe extern "C" fn(user_data: *mut c_void, chunk: *const turbo_generation_chunk) -> u32>;

