/// Name of the symbol a provider library exports.
pub const TURBO_PROVIDER_ENTRY_SYMBOL: &str = "turbo_provider_get";

#[cfg(test)]
mod tests {
    use super::*;
    use core::mem::size_of;

    #[test]
    fn error_is_fixed_size() {
        assert_eq!(size_of::<turbo_error>(), 4 + 4 + 4 + TURBO_ERROR_MESSAGE_LEN);
    }

    #[test]
    fn text_is_two_words() {
        assert_eq!(size_of::<turbo_text>(), 16);
    }

    #[test]
    fn status_grades_do_not_overlap() {
        for (code, grade) in [
            (TURBO_E_INVALID_ARGUMENT, 0x100),
            (TURBO_E_UNSUPPORTED, 0x200),
            (TURBO_E_OUT_OF_MEMORY, 0x300),
            (TURBO_E_DEVICE_NOT_FOUND, 0x400),
            (TURBO_E_BUNDLE_NOT_FOUND, 0x500),
            (TURBO_E_INTERNAL, 0x600),
        ] {
            assert_eq!(code & 0xF00, grade);
        }
    }
}
